// SECURITY GATE: Validate, sanitize, deduplicate, and cap the input batch.
// Addresses: email header injection, HTML injection, XSS, runaway execution,
// duplicate sends, and input length abuse.

const MAX_RECIPIENTS = 500;
const MAX_FIELD_LENGTH = 2000;
const MAX_BODY_LENGTH = 50000;
const EMAIL_REGEX = /^[a-zA-Z0-9.!#$%&'*+\/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;

// HTML-encode to prevent XSS / HTML injection when embedding into email body
function escapeHtml(str) {
  if (typeof str !== 'string') return '';
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

// Strip characters that enable email header injection (CR, LF, null bytes)
function stripHeaderInjection(str) {
  if (typeof str !== 'string') return '';
  return str.replace(/[\r\n\x00]/g, '');
}

// Truncate to a safe length
function truncate(str, max) {
  if (typeof str !== 'string') return '';
  return str.length > max ? str.slice(0, max) : str;
}

const items = $input.all();
const seen = new Set();
const validItems = [];

for (const item of items) {
  const raw = item.json;

  // -- Email validation --
  const email = stripHeaderInjection(truncate((raw.email || '').trim().toLowerCase(), 254));
  if (!email || !EMAIL_REGEX.test(email)) continue;

  // -- Deduplication --
  if (seen.has(email)) continue;
  seen.add(email);

  // -- Recipient cap --
  if (validItems.length >= MAX_RECIPIENTS) break;

  // -- Sanitize all text fields --
  // For fields embedded into HTML: escape HTML entities
  // For fields used in email headers (to, subject): strip injection chars
  const firstName   = escapeHtml(truncate((raw.first_name || '').trim(), MAX_FIELD_LENGTH));
  const lastName    = escapeHtml(truncate((raw.last_name || '').trim(), MAX_FIELD_LENGTH));
  const company     = escapeHtml(truncate((raw.company || '').trim(), MAX_FIELD_LENGTH));
  const customField1 = escapeHtml(truncate((raw.custom_field_1 || '').trim(), MAX_FIELD_LENGTH));
  const customField2 = escapeHtml(truncate((raw.custom_field_2 || '').trim(), MAX_FIELD_LENGTH));

  // Subject: strip header injection chars but do NOT HTML-encode (it's a header, not body)
  const rawSubject  = stripHeaderInjection(truncate((raw.subject || '').trim(), 998));
  const bodyTemplate = truncate((raw.body_template || '').trim(), MAX_BODY_LENGTH);

  validItems.push({
    json: {
      email,
      first_name: firstName,
      last_name: lastName,
      company,
      subject: rawSubject,
      body_template: bodyTemplate,
      custom_field_1: customField1,
      custom_field_2: customField2
    }
  });
}

if (validItems.length === 0) {
  throw new Error('No valid recipient emails found after validation. Check your spreadsheet.');
}

return validItems;

// Compose a personalized email from pre-sanitized input.
// All text fields have already been HTML-encoded and header-injection-stripped
// by the upstream Sanitize node. This node only performs safe placeholder
// substitution — no raw user data touches HTML structure.

const item = $input.first().json;

const firstName   = item.first_name || '';
const lastName    = item.last_name || '';
const company     = item.company || '';
const email       = item.email || '';
const subject     = item.subject || '';
const customField1 = item.custom_field_1 || '';
const customField2 = item.custom_field_2 || '';

// Greeting (already HTML-safe)
const greeting = firstName ? `Hi ${firstName},` : 'Hello,';

// Personalize subject (already header-injection-safe)
const personalizedSubject = subject
  .replace(/\{\{first_name\}\}/gi, firstName)
  .replace(/\{\{last_name\}\}/gi, lastName)
  .replace(/\{\{company\}\}/gi, company)
  .replace(/\{\{custom_field_1\}\}/gi, customField1)
  .replace(/\{\{custom_field_2\}\}/gi, customField2);

// Build body
const bodyTemplate = item.body_template || '';
let htmlBody;

if (bodyTemplate) {
  // User-provided template: all interpolated values are pre-escaped
  htmlBody = bodyTemplate
    .replace(/\{\{greeting\}\}/gi, greeting)
    .replace(/\{\{first_name\}\}/gi, firstName)
    .replace(/\{\{last_name\}\}/gi, lastName)
    .replace(/\{\{company\}\}/gi, company)
    .replace(/\{\{custom_field_1\}\}/gi, customField1)
    .replace(/\{\{custom_field_2\}\}/gi, customField2)
    .replace(/\n/g, '<br>');
} else {
  // Default template — all values are pre-HTML-escaped
  htmlBody = [
    '<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">',
    `  <p>${greeting}</p>`,
    `  <p>${customField1 || 'I wanted to reach out to you regarding an opportunity.'}</p>`,
    company ? `  <p>I noticed your work at <strong>${company}</strong> and thought this would be relevant.</p>` : '',
    customField2 ? `  <p>${customField2}</p>` : '',
    '  <p>Looking forward to hearing from you.</p>',
    '  <p>Best regards</p>',
    '</div>'
  ].filter(Boolean).join('\n');
}

return [{
  json: {
    to: email,
    subject: personalizedSubject || 'No Subject',
    htmlBody: htmlBody
  }
}];
